        class TestModule(torch.nn.Module):
            def __init__(self):
                super().__init__()
                self.param = torch.nn.Parameter(torch.randn(4, 4))

            def forward(self, x):
                self.param.untyped_storage().resize_(
                    self.param.numel() * self.param.itemsize
                )
                with torch.no_grad():
                    torch._foreach_copy_([self.param], [x])
