        self.prefix.writeline(f"""{info_kind}[{idx}].name = "{name}";""")

    @staticmethod
    def get_input_cpp_type(input):
        assert config.use_minimal_arrayref_interface
        from .cpp import DTYPE_TO_CPP

        if isinstance(input, sympy.Expr):
