        key = _winreg.OpenKeyEx(_winreg.HKEY_CURRENT_USER,
                "AppEvents\\Schemes\\Apps\\.Default\\{0}\\.Default".format(sound))
        value = _winreg.EnumValue(key, 0)[1]
